#include<bits/stdc++.h>
using namespace std;
const int N=5e5+1234;
long long n,m,num;
long long a[N],cha[N];
void t(int c){
	long long cnt=1,sum=0;
	for(int i=1;i<=n;i++){
		if(sum+i*c<=m){
			sum+=i*c;
			cnt++;
		}else{cout<<cnt;return ;}
	}
}
int main(){
	freopen("crystal.in","r",stdin);	
	freopen("crystal.out","w",stdout);	
	cin>>n>>m;
	int fl=1;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		if(a[i]!=i) fl=0;
	}
	if(fl==1){t(1);return 0;} 
	sort(a+1,a+n+1);
	int f=1;
	for(int i=2;i<=n;i++){
		cha[i]=a[i]-a[i-1];
		if(cha[i]!=cha[i-1]&&i>2) f=0;
	}
	if(f==0){t(cha[2]);return 0;}
	for(int i=1;i<=n;i++){
		long long sum=0,cnt=1;
		for(int j=i+1;j<=n;j++){
			if(sum+(cha[j]*(j-i))<=m){
				sum+=(cha[j]*(j-i));
				cnt++;
			}else break;
		}
		num=max(cnt,num);
	} 
	cout<<num;
	return 0;
} 
